import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.BEUshCVJ.js";const p=JSON.parse('{"title":"Five-minute tour","description":"","frontmatter":{},"headers":[],"relativePath":"quick-start.md","filePath":"quick-start.md","lastUpdated":1793312058000}'),i={name:"quick-start.md"};function n(s,e,d,h,l,c){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="five-minute-tour" tabindex="-1">Five-minute tour <a class="header-anchor" href="#five-minute-tour" aria-label="Permalink to &quot;Five-minute tour&quot;">​</a></h1><p>This page shows MeetCue working end to end with a recorded sample interview, so you can learn the panel before a real meeting. No API keys or microphone are needed.</p><h2 id="start-the-demo" tabindex="-1">Start the demo <a class="header-anchor" href="#start-the-demo" aria-label="Permalink to &quot;Start the demo&quot;">​</a></h2><ol><li><p>Close MeetCue if it&#39;s running (right-click the tray icon › <strong>Quit MeetCue</strong>).</p></li><li><p>Press <code>Win+R</code>, type the command below and press Enter:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>MeetCue.exe --demo</span></span></code></pre></div><p>If Windows can&#39;t find it, use the full path. With Scoop it&#39;s <code>%USERPROFILE%\\scoop\\apps\\meetcue\\current\\MeetCue.exe</code>.</p></li><li><p>The panel appears on the right side of the screen with a <strong>Demo</strong> tag, and the replay starts after a moment. <code>Ctrl+Alt+Space</code> pauses and resumes it.</p></li></ol><h2 id="what-you-ll-see" tabindex="-1">What you&#39;ll see <a class="header-anchor" href="#what-you-ll-see" aria-label="Permalink to &quot;What you&#39;ll see&quot;">​</a></h2><p>The demo replays an interview for a network engineering role. Watch for these parts of the panel:</p><ol><li><strong>Question card</strong>: about a second and a half after the interviewer finishes a question, a card appears with the question in grey and numbered talking points below it.</li><li><strong>Talking points</strong>: each point has a bold keyword and a few grey words of detail. As the candidate covers a point, it gets a green tick and dims. The next point to cover is highlighted with a <strong>Next</strong> tag.</li><li><strong>Other questions</strong>: when the interviewer cuts in while the candidate is answering, the new question waits as a one-line row marked <strong>Waiting</strong> below the current one. The current hints are not replaced. Click any row to show that question in full.</li><li><strong>Footer</strong>: the latency of the most recent hint. Click it to open the latency probe.</li></ol><h2 id="try-the-shortcuts" tabindex="-1">Try the shortcuts <a class="header-anchor" href="#try-the-shortcuts" aria-label="Permalink to &quot;Try the shortcuts&quot;">​</a></h2><p>While the demo runs, try these shortcuts. They work even though another app has focus.</p><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td><code>Ctrl+Alt+Space</code></td><td>Start or pause listening</td></tr><tr><td><code>Ctrl+Alt+H</code></td><td>Panel: full → mini bar → hidden</td></tr><tr><td><code>Ctrl+Alt+[</code> / <code>Ctrl+Alt+]</code></td><td>Previous / next question</td></tr><tr><td><code>Ctrl+Alt+Enter</code></td><td>Mark the current question answered</td></tr></tbody></table><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li>Set up your providers in <a href="/meetcue/setup">First-time setup</a>.</li><li>Read <a href="/meetcue/guide/meeting">Meeting mode</a> for how questions are detected and queued.</li><li>Test everything over your microphone, without a meeting, in a <a href="/meetcue/guide/mock-interview">mock interview</a>.</li><li>Rehearse with your own questions in <a href="/meetcue/guide/practice">Practice mode</a>.</li></ul>',12)])])}const m=t(i,[["render",n]]);export{p as __pageData,m as default};
